#include <set>
#include <vector>

int main() {
    std::set<int> s;
    std::vector<int> sorted_data = {10, 20, 30, 40};

    // Start with the beginning iterator as the first hint
    auto hint = s.end();

    for (int val : sorted_data) {
        // Use the iterator returned from the previous insertion as the hint
        // This ensures amortized O(1) complexity for sequential data.
        hint = s.insert(hint, val); 
    }
    // Total complexity: O(N) instead of O(N log N)
}
